aufgaben.sysml:
// in Funktionen
action <'F-008'> rampenBefahren {
    doc /* Das Fahrzeug fährt Rampen mit voller Last befahren. */
}

// in Physik::ftf
part <'P-009'> rampenBefahrfahrwerk : Logik::Fahrwerk;

// in Anforderungen
requirement <'R-008'> personenverkehrsgeschwindigkeit {
    doc /* Das FTF fährt in Bereichen mit Personenverkehr höchstens 0,8 m/s. */
}

// in Verknuepfungen
satisfy Anforderungen::personenverkehrsgeschwindigkeit by Physik::ftf.fahrwerk;

// in Anforderungen
requirement <'R-008'> fahrzeugbreite {
    doc /* Das FTF hat eine Breite von höchstens 900 mm. */
}

// in Verknuepfungen
satisfy Anforderungen::fahrzeugbreite by Physik::ftf.sicherheitssteuerung;

// in Anforderungen
requirement <'R-008'> ladestandUnter15Prozent {
    doc /* Das FTF nimmt keine neuen Fahraufträge an, wenn der Akkuladestand unter 15 % liegt. */
}

// in Funktionen
action <'F-008'> ladestandUnterpruefen {
    doc /* Den Akkuladestand prüfen und bei unter 15 % neue Fahraufträge ablehnen. */
}

// in Funktionen
action <'F-008'> zustandsMelden {
    doc /* Das FTF meldet Position, Ladestand und Störungen an das Leitsystem. */
}

// in Anforderungen
requirement <'R-008'> verbindungsverlustAnhalten {
    doc /* Das FTF hält bei Verbindungsverlust von mehr als 5 Sekunden kontrolliert an. */
}

// in Funktionen
action <'F-008'> verbindungsverlustDetektieren {
    doc /* Verbindungsverlust überwachen und bei mehr als 5 Sekunden Halt auslösen. */
}

// in Verknuepfungen
satisfy Anforderungen::verbindungsverlustAnhalten by Physik::ftf.sicherheitssteuerung;

// in Logik
part def <'L-009'> Lastaufnahmesensor {
    doc /* Sensor zur Messung der Aufnahmehöhe von Ladungsträger. */
}

// in Physik::ftf
part <'P-009'> lastaufnahmesensor : Logik::Lastaufnahme;

// in Funktionen
action <'F-008'> lastHandhabenAutomatisch {
    doc /* Ladungsträger automatisch aufnehmen und abgeben. */
}

// in Logik
part def <'L-009'> Lasttragwerk {
    doc /* Mechanik zur Aufnahme und Abgabe von Ladungsträgern. */
}

// in Physik::ftf
part <'P-009'> lasttragwerk : Logik::Lasttragwerk;

// in Verknuepfungen
allocate Funktionen::lastHandhabenAutomatisch to Physik::ftf.lasttragwerk;

// in Anforderungen
requirement <'R-008'> zweischichtbetrieb {
    doc /* Das FTF arbeitet im Zweischichtbetrieb mit 30 Minuten Ladepause zwischen den Schichten. */
}

// in Funktionen
action <'F-008'> ladepauseDurchfuhren {
    doc /* Das FTF hält für 30 Minuten an, um die Akkuleistung zu erholen. */
}

// in Verknuepfungen
satisfy Anforderungen::zweischichtbetrieb by Physik::ftf;

// in Anforderungen
requirement <'R-008'> ladestandUnter15Prozent {
    doc /* Bei einem Akkuladestand unter 15 % nimmt das Fahrzeug keine neuen Fahraufträge an. */
}

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das Fahrzeug fährt selbstständig zur Ladestation, wenn der Akkuladestand unter 15 % liegt. */
}

// in Funktionen
action <'F-008'> akustischeUndOptischeWarnung {
    doc /* Akustische und optische Warnsignale bei Anfahren und Richtungswechseln auslösen. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerRueckwaerts {
    doc /* Sensor, der das Schutzfeld hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> sicherheitslaserscannerRueckwaerts : Logik::Sicherheitslaserscanner;

// in Funktionen
action <'F-008'> stoerungenMelden {
    doc /* Das FTF meldet Störungen an das Leitsystem. */
}

// in Funktionen
action <'F-008'> rueckwaertsFahrenSicherheitsueberwachung {
    doc /* Hinter dem Fahrzeug überwachen und Hindernisse erkennen, wenn das FTF rückwärts fährt. */
}
action <'F-009'> hindernisseErkennenRueckwaerts {
    doc /* Hinter dem Fahrzeug überwachen und Hindernisse erkennen, wenn das FTF rückwärts fährt. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerRueckwaerts {
    doc /* Sensor, der Schutzfelder hinter dem Fahrzeug überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerRueckwaerts : Logik::SicherheitslaserscannerRueckwaerts;

// in Verknuepfungen
allocate Funktionen::rueckwaertsFahrenSicherheitsueberwachung to Physik::ftf.scannerRueckwaerts;
allocate Funktionen::hindernisseErkennenRueckwaerts to Physik::ftf.scannerRueckwaerts;

// in Funktionen
action <'F-008'> optischeWarnung {
    doc /* Optische Warnung durch die Warnleuchte. */
}

// in Logik
part def <'L-009'> Warnleuchte {
    doc /* Leuchte zur optischen Warnung. */
}

// in Physik::ftf
part <'P-009'> warnleuchte : Logik::Warnleuchte;

// in Verknuepfungen
allocate Funktionen::optischeWarnung to Physik::ftf.warnleuchte;

// in Funktionen
action <'F-008'> ladestationAnfahren {
    doc /* Das FTF fährt zur Ladestation und beginnt das kontaktlose Laden. */
}

// in Logik
part def <'L-009'> Ladespule {
    doc /* Elektromagnetische Spule für kontaktloses Laden. */
}

// in Physik::ftf
part <'P-009'> ladespule : Logik::Ladespule;

// in Verknuepfungen
allocate Funktionen::ladestationAnfahren to Physik::ftf.ladespule;

// in Funktionen
action <'F-008'> notHaltAusloesenRechts {
    doc /* Bei Betätigung des Not-Halts auf der rechten Seite alle Antriebe sicher abschalten. */
}

// in Logik
part def <'L-009'> NotHaltTaster {
    doc /* Sensor für den Not-Halt an der rechten Fahrzeugseite. */
}

// in Physik::ftf
part <'P-009'> notHaltTasterRechts : Logik::NotHaltTaster;

// in Verknuepfungen
allocate Funktionen::notHaltAusloesenRechts to Physik::ftf.notHaltTasterRechts;

// in Funktionen
action <'F-008'> hindernisseErkennenHinten {
    doc /* Den Fahrweg im Hintergrund überwachen und Hindernisse sowie Personen erkennen. */
}

// in Logik
part def <'L-009'> SicherheitslaserscannerHinterne {
    doc /* Sensor, der Schutzfelder im Fahrweg überwacht. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::SicherheitslaserscannerHinterne;

// in Verknuepfungen
allocate Funktionen::hindernisseErkennenHinten to Physik::ftf.scannerHinten;

// in Funktionen
action <'F-008'> hindernisseErkennenHinten {
    doc /* Hindernisse im Rückfeld erkennen. */
}

// in Physik::ftf
part <'P-009'> scannerHinten : Logik::Sicherheitslaserscanner;

// in Funktionen
action <'F-008'> akkulaufzeitBesserung {
    doc /* Akkuladung verbessern, um die Einsatzdauer zu erhöhen. */
}

// in Logik
part def <'L-009'> AkkuBessererTyp {
    doc /* Verbesserte Akkutechnologie für höhere Ladungsdauer. */
}

// in Physik::ftf
part <'P-009'> bessererAkku : Logik::AkkuBessererTyp;

// in Anforderungen
requirement <'R-008'> tragekapazitaet {
    doc /* Das FTF kann eine Last von bis zu 2000 kg tragen. */
}

// in Physik::ftf
part <'P-009'> lasttragwerk : Logik::Lastaufnahme;

// in Anforderungen
requirement <'R-008'> maximaleFahrgeschwindigkeitAutomatikbetrieb {
    doc /* Die Höchstgeschwindigkeit im Automatikbetrieb beträgt 3 m/s. */
}

// in Verknuepfungen
satisfy Anforderungen::maximaleFahrgeschwindigkeitAutomatikbetrieb by Physik::ftf.fahrwerk;
